// Re-scores a submitted Spotweld layout with the game's own solver and records it.
const fs=require('fs'),vm=require('vm');
const out=(k,v)=>fs.appendFileSync(process.env.GITHUB_OUTPUT||'/dev/null',`${k}<<EOF\n${v}\nEOF\n`);
const done=(msg,changed=false)=>{console.log(msg);out('msg',msg);out('changed',String(changed));process.exit(0);};
const html=fs.readFileSync('spotweld/index.html','utf8');
const core=html.slice(html.indexOf('const SQ3='),html.indexOf('/* ---------- bot (par)'));
const G=vm.runInNewContext(core+';({DEMOS,prepLevel,evaluate})',{Math,Date,console});
const body=process.env.BODY||'',user=(process.env.USER||'').slice(0,39);
const lv=(body.match(/^level:\s*([a-z0-9]+)\s*$/m)||[])[1],lay=(body.match(/^layout:\s*([0-9a-z]+)\s*$/m)||[])[1];
const d=G.DEMOS.find(x=>x.id===lv);
if(!d||!lay)done('Could not read a level and layout from this issue. Submit from the game with the Submit button.');
const L=G.prepLevel(JSON.parse(JSON.stringify(d)));
const asg=[...lay].map(c=>parseInt(c,36));
if(asg.length!==L.cells.length||asg.some(g=>!(g>=0&&g<L.S)))done(`That layout doesn't fit ${d.name}.`);
const r=G.evaluate(L,asg);
if(!r.complete||r.open||!isFinite(r.total))done(`That layout isn't a complete, connected ${d.S}S${d.P}P pack.`);
const score=Math.round(r.total*100)/100;
const f='spotweld/leaderboard.json',lb=fs.existsSync(f)?JSON.parse(fs.readFileSync(f,'utf8')):{};
const list=lb[lv]||[],prev=list.find(e=>e.user===user);
if(prev&&prev.score<=score)done(`Scored ${score.toFixed(2)} mΩ on ${d.name}. Your best there is still ${prev.score.toFixed(2)} mΩ.`);
lb[lv]=[...list.filter(e=>e.user!==user),{user,score,layout:lay}].sort((a,b)=>a.score-b.score).slice(0,20);
fs.writeFileSync(f,JSON.stringify(lb,null,1)+'\n');
const rank=lb[lv].findIndex(e=>e.user===user)+1;
done(rank?`Recorded ${score.toFixed(2)} mΩ on ${d.name}: #${rank} on the leaderboard. It appears on the site within a couple of minutes.`:`Scored ${score.toFixed(2)} mΩ on ${d.name}, not in the top 20.`,!!rank);
